function timing(origin, phase) {
  const id = typeof origin === 'string' ? origin : '';
  const response = phase === 'result' ? '剛才那句我聽到了，現在換我說：' : '';
  if (id === 'onboarding') return {
    line: `${response}我才剛報到，先把話講清楚：`,
    after: '報到手續都還沒走完，你已經先讓這張新門禁卡聽見自己的聲音。'
  };
  if (/pip|hope-care/.test(id)) return {
    line: `${response}改善表先放旁邊，這句算我的口頭回饋：`,
    after: '真正的改善表仍在眼前，這句話沒有替你自動填完目標，也沒有憑空決定評核結果。'
  };
  if (/salary|raise|low-pay/.test(id)) return {
    line: `${response}薪水先別拿態度結帳，我講一句：`,
    after: '薪資數字沒有因為你罵完就自己改好，眼前那項安排仍要另外確認。'
  };
  if (/banquet|first-love|armwrestling/.test(id)) return {
    line: `${response}這句不用配樂，我自己開麥：`,
    after: '剛才那句真的越過了桌邊，沒有被伴奏蓋掉；這次不是腦內彩排。'
  };
  if (id.startsWith('meal-with-')) return {
    line: `${response}先放下筷子，我不想再把這句配飯吞：`,
    after: '你說完還坐在原來的位置，眼前仍是那頓飯；這句話不會替餐費重算一次。'
  };
  if (/floor|watch/.test(id)) return {
    line: `${response}樓層換了，我的嘴還沒辦離職：`,
    after: '這句真的從待命的位置傳出去了，卻不會單靠音量把你送回原來的工作。'
  };
  if (/career-review|promotion-review|patronage|appointment/.test(id)) return {
    line: `${response}新職稱先別印，先聽完這句：`,
    after: '名片還沒換，你先換了一種說話方式；任用與評核仍得面對接下來的決定。'
  };
  return {
    line: response,
    after: phase === 'result' ? '這是聽完剛才回覆後真的說出口的話，不會把已經發生的選擇倒帶。' : '這回你真的開了口，沒有伸手，也沒有把整段留在腦海裡。'
  };
}

export function verbalVoiceV30(target, origin, phase, run) {
  if(isCastV74(run)&&CAST_IDS_V74.includes(target))return {name:CAST_PROFILES_V74[target].name,line:`${CAST_PROFILES_V74[target].name}，幹，眼前這件事先講清楚。誰答應哪段就照原話留下，不要把每個空格都丟給同一個人。`,...castVerbalReactionsV74(target,{privateScene:/^meal-with-/.test(origin||'')})};
  if(/^e39-/.test(run?.seed||'')&&CAST_IDS_V39.includes(target))return castVerbalVoiceV39(target,origin,phase);
  if(target==='professor'&&/^e(?:37|38|39)-/.test(run?.seed||''))return professorVerbalVoiceV37(origin,phase);
  const voice = VOICES[Object.hasOwn(VOICES, target) ? target : 'self'];
  const context = timing(origin, phase);
  return { ...voice, line: `${context.line}${voice.line}`, ignored: `${voice.ignored}${context.after}` };
}
